const cache = new Map();
export function getBakedSprite(key) {
  let s = cache.get(key);
  if (s) return s;
  const rec = RAW_SPRITES[key];
  if (!rec) return null;
  const [w, h, b64] = rec;
  const bin = atob(b64);
  const d = new Uint8Array(w * h);
  let p = 0;
  for (let i = 0; i < bin.length; i++) {
    const b = bin.charCodeAt(i);
    if (b === 254) {
      const run = bin.charCodeAt(++i);
      const val = bin.charCodeAt(++i);
      d.fill(val, p, p + run);
      p += run;
    } else {
      d[p++] = b;
    }
  }
  s = { w, h, d };
  cache.set(key, s);
  return s;
}
